@Service
public class ImportExportService {

    private static final String METADATA_ENTRY = "_metadata.yml";

    private final NamespaceMapper namespaceMapper;
    private final ConfigMapper configMapper;
    private final ImportRecordMapper importRecordMapper;

    public ImportExportService(NamespaceMapper namespaceMapper,
                               ConfigMapper configMapper,
                               ImportRecordMapper importRecordMapper) {
        this.namespaceMapper = namespaceMapper;
        this.configMapper = configMapper;
        this.importRecordMapper = importRecordMapper;
    }

    public byte[] exportNamespace(Long namespaceId) {
        Namespace namespace = namespaceMapper.findById(namespaceId);
        List<Config> configs = configMapper.findByNamespaceId(namespaceId);
        Yaml yaml = blockStyleYaml();
        try (ByteArrayOutputStream out = new ByteArrayOutputStream();
             ZipOutputStream zip = new ZipOutputStream(out)) {

            Map<String, Object> metadata = new LinkedHashMap<>();
            metadata.put("exportTime", LocalDateTime.now().toString());
            metadata.put("namespace", namespace != null ? namespace.getName() : "unknown");
            metadata.put("configCount", configs.size());
            metadata.put("version", "1.0");
            zip.putNextEntry(new ZipEntry(METADATA_ENTRY));
            zip.write(yaml.dump(metadata).getBytes(StandardCharsets.UTF_8));
            zip.closeEntry();

            for (Config config : configs) {
                String entryName = config.getGroupName() + "_" + config.getDataId();
                if (!entryName.endsWith(".yml") && !entryName.endsWith(".yaml")) {
                    entryName += ".yml";
                }
                Map<String, Object> body = new LinkedHashMap<>();
                body.put("dataId", config.getDataId());
                body.put("groupName", config.getGroupName());
                body.put("format", config.getFormat());
                body.put("content", config.getContent());
                zip.putNextEntry(new ZipEntry(entryName));
                zip.write(yaml.dump(body).getBytes(StandardCharsets.UTF_8));
                zip.closeEntry();
            }

            zip.finish();
            return out.toByteArray();
        } catch (Exception e) {
            throw new IllegalStateException("Failed to export namespace " + namespaceId, e);
        }
    }

    public ImportRecord importConfigs(Long namespaceId, Long userId, MultipartFile file) {
        int imported = 0;
        int failed = 0;
        String status;
        try {
            Path temp = Files.createTempFile("confighub-import-", ".zip");
            try {
                Files.write(temp, file.getBytes());
                try (ZipFile zipFile = new ZipFile(temp.toFile())) {
                    Enumeration<? extends ZipEntry> entries = zipFile.entries();
                    while (entries.hasMoreElements()) {
                        ZipEntry entry = entries.nextElement();
                        if (entry.isDirectory()) {
                            continue;
                        }
                        String name = entry.getName();
                        if (METADATA_ENTRY.equals(name)
                                || (!name.endsWith(".yml") && !name.endsWith(".yaml"))) {
                            continue;
                        }
                        try {
                            String text;
                            try (InputStream in = zipFile.getInputStream(entry)) {
                                text = new String(in.readAllBytes(), StandardCharsets.UTF_8);
                            }
                            if (importEntry(namespaceId, text)) {
                                imported++;
                            } else {
                                failed++;
                            }
                        } catch (Exception e) {
                            failed++;
                        }
                    }
                }
            } finally {
                Files.deleteIfExists(temp);
            }
            if (failed == 0) {
                status = "SUCCESS";
            } else if (imported > 0) {
                status = "PARTIAL";
            } else {
                status = "FAILED";
            }
        } catch (Exception e) {
            imported = 0;
            failed = 0;
            status = "FAILED";
        }

        ImportRecord record = new ImportRecord();
        record.setNamespaceId(namespaceId);
        record.setUserId(userId);
        record.setFilename(file.getOriginalFilename());
        record.setStatus(status);
        record.setImportedCount(imported);
        record.setFailedCount(failed);
        record.setCreatedAt(LocalDateTime.now());
        importRecordMapper.insert(record);
        return record;
    }

    public List<ImportRecord> listImportRecords(Long namespaceId) {
        return importRecordMapper.findByNamespaceId(namespaceId);
    }

    private boolean importEntry(Long namespaceId, String text) {
        Object loaded = new Yaml(new SafeConstructor()).load(text);
        if (!(loaded instanceof Map<?, ?> data)) {
            return false;
        }
        Object dataIdValue = data.get("dataId");
        Object contentValue = data.get("content");
        if (dataIdValue == null || contentValue == null) {
            return false;
        }
        String dataId = dataIdValue.toString();
        String content = contentValue.toString();
        String groupName = data.get("groupName") != null
                ? data.get("groupName").toString() : ConfigService.DEFAULT_GROUP;
        String format = data.get("format") != null
                ? data.get("format").toString() : ConfigService.DEFAULT_FORMAT;

        LocalDateTime now = LocalDateTime.now();
        Config existing = configMapper.findByNamespaceIdAndDataIdAndGroupName(namespaceId, dataId, groupName);
        if (existing != null) {
            existing.setContent(content);
            existing.setFormat(format);
            existing.setVersion(existing.getVersion() + 1);
            existing.setUpdatedAt(now);
            configMapper.update(existing);
        } else {
            Config config = new Config();
            config.setNamespaceId(namespaceId);
            config.setDataId(dataId);
            config.setGroupName(groupName);
            config.setContent(content);
            config.setFormat(format);
            config.setVersion(1);
            config.setUpdatedAt(now);
            config.setCreatedAt(now);
            configMapper.insert(config);
        }
        return true;
    }

    private Yaml blockStyleYaml() {
        DumperOptions options = new DumperOptions();
        options.setDefaultFlowStyle(DumperOptions.FlowStyle.BLOCK);
        return new Yaml(options);
    }
}
